using System;using System.Collections.Generic;
class Program {
static int checks;static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;}
class Context {
public Vector3i Pos=new Vector3i(4,5,6);public WorldBase World=new WorldBase();public TileEntityPlantGrowingRebirth Source,Target;public BlockValue From,To;public BlockPlantGrowing Native=new BlockPlantGrowing{nextPlant=new BlockValue{type=3}};public List<string> Trace=new List<string>();
public Context(AdvancedFarmingPlantOrigin origin=AdvancedFarmingPlantOrigin.Player){AdvancedFarmingHoverTextService.Reset();Source=new TileEntityPlantGrowingRebirth{PlantIncarnation=100,StateRevision=10,PlantOrigin=origin};Target=new TileEntityPlantGrowingRebirth{PlantIncarnation=200,StateRevision=20,PlantOrigin=AdvancedFarmingPlantOrigin.Unknown};From=new BlockValue{type=1,rotation=2,meta=3,meta2=4,damage=5};To=new BlockValue{type=2,rotation=3,meta=4,meta2=5,damage=6,Block=Native};World.Blocks[Pos]=From;World.Tiles[Pos]=Source;}
public AdvancedFarmingPlantOriginService.NativeTransition Begin()=>AdvancedFarmingPlantOriginService.BeginNativeTransition(World,Pos,From,To,Source);
// Qualified Chunk.SetBlock2305 publishes target BEFORE old OnBlockRemoved2308,
// then native OnBlockAdded2324. Tile creation/removal and hook insertion are stubs.
public void Mutation(Action during=null,TileEntityPlantGrowingRebirth target=null){World.Blocks[Pos]=To;Trace.Add("publish target");during?.Invoke();AdvancedFarmingPlantOriginService.OnNativePlantRemoving(World,Pos,From,Source);Trace.Add("old removal hook");World.Tiles.Remove(Pos);Trace.Add("native old TE removed");World.Tiles[Pos]=target??Target;Trace.Add("native target TE published");AdvancedFarmingPlantOriginService.OnNativePlantAdded(World,Pos,To,target??Target);Trace.Add("new add hook");}
public TileEntityPlantGrowingRebirth Replace(ulong incarnation=201){var replacement=new TileEntityPlantGrowingRebirth{PlantIncarnation=incarnation,StateRevision=30,PlantOrigin=AdvancedFarmingPlantOrigin.Player};World.Tiles[Pos]=replacement;return replacement;}
}
static void Happy(){foreach(var origin in new[]{AdvancedFarmingPlantOrigin.Player,AdvancedFarmingPlantOrigin.Unknown,AdvancedFarmingPlantOrigin.System}){var c=new Context(origin);using(var scope=c.Begin()){Check(scope!=null&&scope.BeforeMutation(),"authoritative current source admits one mutation");c.Mutation();Check(c.Target.PlantOrigin==origin&&AdvancedFarmingPlantOriginService.IsPlayerPlanted(c.World,c.Pos)==(origin==AdvancedFarmingPlantOrigin.Player),"native transition preserves explicit Player/Unknown/System without inventing Player");Check(scope.Complete()&&c.Target.Modified==1&&AdvancedFarmingHoverTextService.Invalidations==1,"valid completion marks exact target and invalidates once");Check(!scope.Complete(),"completion is one use");}Check(c.Target.PlantOrigin==origin&&c.Native.Scheduled==0&&c.World.Scheduler.Invalidations==0,"finished disposal does not schedule cleanup");Check(string.Join("|",c.Trace)=="publish target|old removal hook|native old TE removed|native target TE published|new add hook","native callback order captured explicitly");}}
static void Refusals(){var c=new Context();using(var scope=c.Begin()){Check(scope.BeforeMutation()&&!scope.BeforeMutation(),"BeforeMutation is one use");c.Mutation();Check(c.Target.PlantOrigin==AdvancedFarmingPlantOrigin.Unknown&&!scope.Complete(),"repeated Before invalidates origin propagation");}
c=new Context();using(var scope=c.Begin()){c.Source.StateRevision++;Check(!scope.BeforeMutation(),"revision change before native mutation refuses");}
c=new Context();using(var scope=c.Begin()){Check(scope.BeforeMutation(),"before revision-during test");c.Mutation(()=>c.Source.StateRevision++);Check(c.Target.PlantOrigin==AdvancedFarmingPlantOrigin.Unknown&&!scope.Complete(),"source revision during native publication prevents origin transfer");}
c=new Context();using(var scope=c.Begin()){Check(scope.BeforeMutation(),"before nested test");Check(c.Begin()==null,"same-position nested transition refuses");c.Mutation();Check(c.Target.PlantOrigin==AdvancedFarmingPlantOrigin.Unknown&&!scope.Complete(),"nested attempt invalidates first pending transition");}
c=new Context();var delayed=c.Begin();Check(delayed.BeforeMutation(),"before delayedcomplete test");c.Mutation();delayed.Dispose();Check(!delayed.Complete()&&c.Target.PlantOrigin==AdvancedFarmingPlantOrigin.Unknown,"Complete after Dispose cannot resurrect Player");Check(c.Target.Advanced==1&&c.World.Scheduler.Invalidations==1&&c.Native.Scheduled==1,"failed admission cleanup cancels custom schedule then restores native schedule once");delayed.Dispose();Check(c.Native.Scheduled==1,"Dispose idempotent");
c=new Context();using(var scope=c.Begin()){scope.BeforeMutation();c.Mutation(target:c.Source);Check(c.Source.PlantOrigin==AdvancedFarmingPlantOrigin.Unknown&&!scope.Complete(),"same source reused as target cannot inherit Player");}
c=new Context();c.Target.PlantIncarnation=c.Source.PlantIncarnation;using(var scope=c.Begin()){scope.BeforeMutation();c.Mutation();Check(c.Target.PlantOrigin==AdvancedFarmingPlantOrigin.Unknown&&!scope.Complete(),"target incarnation reused refuses");}
c=new Context();using(var scope=c.Begin()){scope.BeforeMutation();c.Mutation();c.Target.PlantIncarnation++;Check(!scope.Complete(),"target new incarnation refuses");}Check(c.Target.PlantOrigin==AdvancedFarmingPlantOrigin.Player&&c.Target.Advanced==0&&c.Native.Scheduled==0,"old scope does not clean new incarnation");
c=new Context();using(var scope=c.Begin()){scope.BeforeMutation();c.Mutation();c.Target.StateRevision++;Check(!scope.Complete(),"changed target revision refuses completion");}Check(c.Target.PlantOrigin==AdvancedFarmingPlantOrigin.Player&&c.Target.Advanced==0&&c.Native.Scheduled==0,"newer target revision preserved without cleanup");
c=new Context();c.World.Remote=true;Check(c.Begin()==null,"remote world cannot begin authoritative scope");
c=new Context();c.World.Blocks[c.Pos]=c.To;c.World.Tiles[c.Pos]=c.Target;c.Target.PlantOrigin=AdvancedFarmingPlantOrigin.Player;AdvancedFarmingPlantOriginService.OnNativePlantAdded(c.World,c.Pos,c.To,c.Target);Check(c.Target.PlantOrigin==AdvancedFarmingPlantOrigin.Player&&AdvancedFarmingPlantOriginService.IsPlayerPlanted(c.World,c.Pos),"unscoped repeated add preserves an existing authoritative identity");}
static void CallbackReplacement(){foreach(string callback in new[]{"CompleteModified","CompleteHover","CleanupCancel","CleanupModified","CleanupHover"}){var c=new Context();var scope=c.Begin();scope.BeforeMutation();c.Mutation();TileEntityPlantGrowingRebirth replacement=null;Action replace=()=>replacement=c.Replace(c.Target.PlantIncarnation);
if(callback=="CompleteModified")c.Target.OnModified=replace;else if(callback=="CompleteHover")AdvancedFarmingHoverTextService.OnInvalidate=replace;else{c.Source.StateRevision++;if(callback=="CleanupCancel")c.World.Scheduler.OnInvalidate=replace;else if(callback=="CleanupModified")c.Target.OnModified=replace;else AdvancedFarmingHoverTextService.OnInvalidate=replace;}
Check(!scope.Complete(),"callback or revision invalidates completion "+callback);scope.Dispose();Check(replacement!=null&&ReferenceEquals(c.World.GetTileEntity(c.Pos),replacement)&&replacement.PlantOrigin==AdvancedFarmingPlantOrigin.Player&&replacement.StateRevision==30&&replacement.Modified==0&&replacement.Advanced==0,"replacement exact identity not mutated "+callback);Check(c.Native.Scheduled==0,"callback replacement never receives native restored schedule "+callback);}}
static void CallbackFailures(){var c=new Context();var scope=c.Begin();scope.BeforeMutation();c.Mutation();c.Target.OnModified=()=>c.Source.StateRevision++;Check(!scope.Complete(),"source revision changed by modified callback invalidates completion");c.Target.OnModified=null;scope.Dispose();Check(c.Target.PlantOrigin==AdvancedFarmingPlantOrigin.Unknown&&c.Native.Scheduled==1,"callback-invalidated exact admission cleaned back to native Unknown");
c=new Context();scope=c.Begin();scope.BeforeMutation();c.Mutation();c.Target.OnModified=()=>{if(c.Target.Modified==1)throw new InvalidOperationException("fixture modifier callback");};bool threw=false;try{scope.Complete();}catch(InvalidOperationException){threw=true;}scope.Dispose();Check(threw&&c.Target.PlantOrigin==AdvancedFarmingPlantOrigin.Unknown&&c.Target.Modified==2&&c.Native.Scheduled==1,"throwing completion callback leaves cleanup/native schedule available");
c=new Context();scope=c.Begin();scope.BeforeMutation();c.Mutation();c.Source.StateRevision++;Check(!scope.Complete(),"before cleanup throw");c.Target.OnModified=()=>throw new InvalidOperationException("fixture cleanup callback");threw=false;try{scope.Dispose();}catch(InvalidOperationException){threw=true;}Check(threw&&c.Target.PlantOrigin==AdvancedFarmingPlantOrigin.Unknown&&c.Native.Scheduled==1&&AdvancedFarmingHoverTextService.Invalidations==1,"cleanup finally restores native fallback despite modifier throw");c.Target.OnModified=null;var next=AdvancedFarmingPlantOriginService.BeginNativeTransition(c.World,c.Pos,c.To,c.From,c.Target);Check(next!=null,"cleanup finally removes failed active scope");next.Dispose();}
static void Main(){LocalFixture.Run();Happy();Refusals();CallbackReplacement();CallbackFailures();Console.WriteLine("PASS "+checks+" linked current origin-service behavior checks. World/TE/block/WBT/hover/native callback and scheduling are focused stubs; Chunk ordering qualified separately; no native engine/authority/installer/game claim.");}
}